/* a hole's expression of one value (stencil_census.EXPRESSIONS, in order) */
static u64 vmc_expression(int e, u64 u) {
    s64 v = (s64)u;
    (void)v;
    switch (e) {
    case 0: return u;   /* v */
    case 1: return u;   /* v mod 2^64 */
    case 2: return u - 1000;   /* xmm */
    case 3: return u >> 0 & 0xFFFF;   /* halfword 0 */
    case 4: return u >> 16 & 0xFFFF;   /* halfword 1 */
    case 5: return u >> 32 & 0xFFFF;   /* halfword 2 */
    case 6: return u >> 48 & 0xFFFF;   /* halfword 3 */
    case 7: return u & 0xFFF;   /* low 12 bits */
    case 8: return u >> 12 & 0xFFF;   /* bits 12-23 */
    case 9: return u & 0xFFu;   /* masked to 8 bits */
    case 10: return u & 0xFFFFu;   /* masked to 16 bits */
    case 11: return u & 0xFFFFFFFFu;   /* masked to 32 bits */
    case 12: return -u;   /* -v */
    case 13: return -u;   /* -v mod 2^64 */
    case 14: return -u & 0xFFFFFFFFu;   /* -v mod 2^32 */
    case 15: return 16 * (u - 1000);   /* 16 x xmm */
    case 16: return u & 31;   /* low 5 bits */
    case 17: return (u & 31) - 1;   /* low 5 bits - 1 */
    case 18: return 32 - (u & 31);   /* 32 - low 5 bits */
    case 19: return u & 63;   /* low 6 bits */
    case 20: return (u & 63) - 1;   /* low 6 bits - 1 */
    case 21: return 64 - (u & 63);   /* 64 - low 6 bits */
    case 22: return u - 1;   /* v - 1 */
    case 23: return 8 - u;   /* 8 - v */
    case 24: return 16 - u;   /* 16 - v */
    case 25: return 32 - u;   /* 32 - v */
    case 26: return 64 - u;   /* 64 - v */
    case 27: return u >> 0 & 3;   /* bits 0+2 */
    case 28: return u >> 2 & 3;   /* bits 2+2 */
    case 29: return u >> 4 & 3;   /* bits 4+2 */
    case 30: return u >> 6 & 3;   /* bits 6+2 */
    case 31: return u >> 0 & 1;   /* bits 0+1 */
    case 32: return u >> 1 & 1;   /* bits 1+1 */
    case 33: return u >> 2 & 1;   /* bits 2+1 */
    case 34: return u >> 3 & 1;   /* bits 3+1 */
    case 35: return u >> 4 & 1;   /* bits 4+1 */
    case 36: return u >> 5 & 1;   /* bits 5+1 */
    case 37: return u >> 6 & 1;   /* bits 6+1 */
    case 38: return u >> 7 & 1;   /* bits 7+1 */
    case 39: return u >> 1 & 3;   /* bits 1+2 */
    case 40: return u >> 3 & 3;   /* bits 3+2 */
    case 41: return u >> 5 & 3;   /* bits 5+2 */
    case 42: return u >> 7 & 3;   /* bits 7+2 */
    case 43: return u >> 0 & 7;   /* bits 0+3 */
    case 44: return u >> 1 & 7;   /* bits 1+3 */
    case 45: return u >> 2 & 7;   /* bits 2+3 */
    case 46: return u >> 3 & 7;   /* bits 3+3 */
    case 47: return u >> 4 & 7;   /* bits 4+3 */
    case 48: return u >> 5 & 7;   /* bits 5+3 */
    case 49: return u >> 6 & 7;   /* bits 6+3 */
    case 50: return u >> 7 & 7;   /* bits 7+3 */
    case 51: return u >> 0 & 15;   /* bits 0+4 */
    case 52: return u >> 1 & 15;   /* bits 1+4 */
    case 53: return u >> 2 & 15;   /* bits 2+4 */
    case 54: return u >> 3 & 15;   /* bits 3+4 */
    case 55: return u >> 4 & 15;   /* bits 4+4 */
    case 56: return u >> 5 & 15;   /* bits 5+4 */
    case 57: return u >> 6 & 15;   /* bits 6+4 */
    case 58: return u >> 7 & 15;   /* bits 7+4 */
    case 59: return (u64)(v < 8 ? v : 8);   /* min(v, 8) */
    case 60: return (u64)(v < 16 ? v : 16);   /* min(v, 16) */
    case 61: return (u64)(v < 32 ? v : 32);   /* min(v, 32) */
    case 62: return (u64)(v < 64 ? v : 64);   /* min(v, 64) */
    case 63: return (u64)(v < 7 ? v : 7);   /* min(v, 7) */
    case 64: return (u64)(v < 15 ? v : 15);   /* min(v, 15) */
    case 65: return (u64)(v < 31 ? v : 31);   /* min(v, 31) */
    case 66: return (u64)(v < 63 ? v : 63);   /* min(v, 63) */
    }
    return 0;
}

/* a refinement's feature of one value (stencil_table.FEATURES, in order) */
static u64 vmc_feature(int f, u64 u) {
    switch (f) {
    case 0: return (u & 0xFF) >= 8;   /* at least 8 */
    case 1: return (u & 0xFF) >= 16;   /* at least 16 */
    case 2: return (u & 0xFF) >= 32;   /* at least 32 */
    case 3: return (u & 0xFF) >= 64;   /* at least 64 */
    case 4: return (u & 0xFF) >= 128;   /* at least 128 */
    case 5: return u & 1;   /* low 1 bits */
    case 6: return u & 3;   /* low 2 bits */
    case 7: return u & 7;   /* low 3 bits */
    case 8: return u & 15;   /* low 4 bits */
    case 9: return u & 31;   /* low 5 bits */
    }
    return 0;
}

/* an item's encoder called on its arguments: the word count, 0 where the encoder refuses them */
